steps.seedCode:
const redis = require('redis');
const http = require('http');

const redisClient = redis.createClient();

const server = http.createServer((req, res) => {
  const url = req.url;
  const method = req.method;

  if (url === '/revoke' && method === 'POST') {
    let body = '';
    req.on('data', chunk => {
      body += chunk.toString();
    });
    req.on('end', () => {
      const data = JSON.parse(body);
      const token = data.token;
      const ttl = data.ttl || 3600;

      redisClient.setEx(`revoked:${token}`, ttl, 'true', (err, reply) => {
        if (err) {
          res.writeHead(500, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Revocation failed' }));
          return;
        }
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ message: 'Token revoked', token }));
      });
    });
  } else if (url === '/validate' && method === 'GET') {
    const token = req.headers.authorization?.split(' ')[1];
    if (!token) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Token missing' }));
      return;
    }

    redisClient.get(`revoked:${token}`, (err, reply) => {
      if (err) {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Validation failed' }));
        return;
      }
      if (reply === 'true') {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ valid: false, message: 'Token revoked' }));
      } else {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ valid: true, message: 'Token valid' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

